import { cache } from "react";

import type { FileRef, PaginatedResponse } from "@repo/shared/types";

// Reads of the public categories API, for a client with no signed-in user.
//
// Generated by grit with --public, and not overwritten when the resource is
// regenerated: the Go side's allowlist is yours to edit, and this file is typed
// against it.
//
// These call /public/categories, not the authenticated routes the hooks in
// hooks/use-categories.ts call. The authenticated ones answer 401
// without a session, which is correct for the admin panel and useless here.

const API_URL = (
  process.env.API_INTERNAL_URL ||
  process.env.NEXT_PUBLIC_API_URL ||
  "http://localhost:8080"
).replace(/\/+$/, "");

// Publishable by design: it reaches the read-only public endpoints and nothing
// else, which is why the seeder writes it as NEXT_PUBLIC_.
const API_KEY = process.env.NEXT_PUBLIC_API_KEY ?? "";

// Pages revalidate on this interval, so an edit in the admin shows within a
// minute without a deploy.
const REVALIDATE_SECONDS = 60;

// PublicCategory is the published shape: the allowlist in
// internal/handlers/category_public.go, not the model. Add a field
// there and add it here.
export interface PublicCategory {
  id: string;
  parent_id: string;
  depth: number;
  descendant_ids?: string[];
  name: string;
  slug: string;
  image: FileRef | null;
  featured: boolean;
}

export type PublicCategoryPage = {
  data: PublicCategory[];
  meta: PaginatedResponse<PublicCategory>["meta"] | undefined;
};

async function publicGet<T>(path: string): Promise<{ status: number; body: T | null }> {
  try {
    const res = await fetch(API_URL + path, {
      headers: API_KEY ? { "X-API-Key": API_KEY } : {},
      next: { revalidate: REVALIDATE_SECONDS },
    });
    if (!res.ok) return { status: res.status, body: null };
    return { status: res.status, body: (await res.json()) as T };
  } catch {
    // The API is unreachable, as it is while a production build runs in CI. A
    // list renders empty and fills in on the next request rather than failing
    // the build.
    return { status: 0, body: null };
  }
}

// One page of categories. Every search, sort, filter and range the
// public handler allows is a query parameter; anything it does not allow is
// ignored rather than rejected.
export const getPublicCategories = cache(async (
  params: Record<string, string | number | undefined> = {}
): Promise<PublicCategoryPage> => {
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined && value !== "") query.set(key, String(value));
  }
  const suffix = query.toString() ? "?" + query.toString() : "";
  const { body } = await publicGet<PaginatedResponse<PublicCategory>>("/api/v1/public/categories" + suffix);
  return { data: body?.data ?? [], meta: body?.meta };
});

// One category by its public key, or null when there is none.
//
// A row that is archived or switched off is a 404 here, the same as one that
// never existed: whether it exists is itself not public. An API that fails is
// an error rather than a missing row, so it is not reported as null.
export const getPublicCategory = cache(async (key: string): Promise<PublicCategory | null> => {
  const { status, body } = await publicGet<{ data: PublicCategory }>(
    "/api/v1/public/categories/" + encodeURIComponent(key)
  );
  if (status === 404) return null;
  if (!body) throw new Error("the public category API answered " + (status || "nothing") + " for " + key);
  return body.data;
});

// The "similar items" strip on a detail page. The server caps the limit, so
// asking for more than it allows returns what it allows.
export const getRelatedCategories = cache(async (
  key: string,
  limit = 8
): Promise<PublicCategory[]> => {
  const { body } = await publicGet<{ data: PublicCategory[] }>(
    "/api/v1/public/categories/" + encodeURIComponent(key) + "/related?limit=" + limit
  );
  return body?.data ?? [];
});

// The whole tree, assembled by the server: parents before children, siblings in
// the order the admin arranged. One request rather than one per level.
export interface PublicCategoryNode extends PublicCategory {
  children: PublicCategoryNode[];
}

export const getPublicCategoriesTree = cache(async (): Promise<PublicCategoryNode[]> => {
  const { body } = await publicGet<{ data: PublicCategoryNode[] }>("/api/v1/public/categories/tree");
  return body?.data ?? [];
});
